import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    N = int(sys.stdin.readline())
    adj = [[] for _ in range(N)]
    for _ in range(N):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)

    max_total = 0

    def dfs(u, parent, subtree_size):
        size = 1
        for v in adj[u]:
            if v != parent:
                child_size = dfs(v, u, subtree_size)
                size += child_size
        subtree_size[u] = size
        return size

    subtree_size = [0] * N
    dfs(0, -1, subtree_size)

    def compute_potential(start):
        total = 0
        inactive = [True] * N
        inactive[start] = False
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if inactive[v]:
                    inactive[v] = False
                    q.append(v)
        order = []
        while True:
            found = False
            for u in range(N):
                if inactive[u]:
                    order.append(u)
                    inactive[u] = False
                    q = deque([u])
                    while q:
                        v = q.popleft()
                        for w in adj[v]:
                            if inactive[w]:
                                inactive[w] = False
                                q.append(w)
                    found = True
                    break
            if not found:
                break
        inactive = [True] * N
        for u in order:
            component = []
            q = deque([u])
            inactive[u] = False
            component.append(u)
            while q:
                v = q.popleft()
                for w in adj[v]:
                    if inactive[w]:
                        inactive[w] = False
                        component.append(w)
                        q.append(w)
            total += len(component)
        return total

    for start in range(N):
        current_total = 0
        inactive = [True] * N
        inactive[start] = False
        order = []
        q = deque([start])
        while q:
            u = q.popleft()
            order.append(u)
            for v in adj[u]:
                if inactive[v]:
                    inactive[v] = False
                    q.append(v)
        inactive = [True] * N
        for u in order:
            component = []
            q = deque([u])
            inactive[u] = False
            component.append(u)
            while q:
                v = q.popleft()
                for w in adj[v]:
                    if inactive[w]:
                        inactive[w] = False
                        component.append(w)
                        q.append(w)
            current_total += len(component)
        if current_total > max_total:
            max_total = current_total

    print(max_total)

if __name__ == "__main__":
    main()
